type RecallResult = 'correct' | 'incorrect';

interface Card {
  id: string;
  deckId: string;
  frontText: string;
  backText: string;
  contentVersion: number;
  hint?: string;
}

interface StudySession {
  sessionId: string;
  deckId: string;
  cardIds: string[];
  currentCardId: string | null;
  revealed: boolean;
}

interface ScheduleState {
  cardId: string;
  dueAt: number;
  revision: string;
}

interface ProgressCommand {
  commandId: string;
  sessionId: string;
  deckId: string;
  cardId: string;
  result: RecallResult;
  answeredAt: number;
  baseRevision: string;
}

interface ProgressQueueItem {
  command: ProgressCommand;
  attempts: number;
  lastAttemptAt?: number;
}
